import { useState } from 'react';

export function BotonLike({ postId, likesIniciales }) {
  const [likes, setLikes] = useState(likesIniciales);
  const [dioLike, setDioLike] = useState(false);

  async function alternarLike() {
    setDioLike(!dioLike);
    setLikes(dioLike ? likes - 1 : likes + 1);

    await fetch(`/api/posts/${postId}/like`, {
      method: dioLike ? 'DELETE' : 'POST',
    });
  }

  return (
    <div className="like">
      <span onClick={alternarLike}>{dioLike ? '❤️' : '🤍'}</span>
      <span>{likes} {likes === 1 ? 'like' : 'likes'}</span>
    </div>
  );
}

